window.AVAL_MAPA = {"produto":{"nome":"Prêmio IEL","desc":"","path":"global/MASTER.md"},"dominios":[{"folder":"acesso","nome":"Acesso e Gestão","sigla":"ACS","desc":"Responde pelo controle de acesso e pela gestão dos administradores regionais, apoiando-se no login corporativo (SSO) para a identidade e mantendo o vínculo de cada administrador às suas UFs. Concentra a auditoria das ações críticas do sistema. É consumido por todos os domínios, que dependem do perfil do usuário e do seu escopo regional para autorizar cada ação.","path":"modules/acesso/README.md","fss":[{"nome":"Acesso e Perfis","sigla":"ACS-ACE","desc":"Cuida da entrada do usuário no sistema e da resolução do seu perfil e das funcionalidades autorizadas, apoiando-se no login corporativo (SSO/AD) para a identidade. O controle de acesso é por funcionalidade e nega por padrão, com um perfil por usuário (ver `global/AUTHZ.md`). ⚠️ *Feature Set sem HU dedicada — derivado de AUTHZ e do N0 (SSO); a confirmar.*","path":"modules/acesso/acesso-perfis/README.md","feats":[{"id":"ACS-ACE-01","nome":"Autenticar Usuário","desc":"Permite ao usuário entrar no sistema pelo login corporativo do Sistema Indústria (SSO), autenticando a sua identidade para iniciar uma sessão com o perfil correspondente. ⚠️ *(autenticação externa ao produto — a confirmar se figura como feature)*","objeto":"**ALI: Usuário** · entidade principal (vínculo usuário↔UF; escopo dos administradores regionais; e-mail local) ⚠️ `CD_USUARIO` é a chave da identidade externa (SSO/AD) — não há tabela local de usuário; o vínculo por UF é o único dado de usuário persistido neste schema.","uso":"","estado":"rascunho","prioridade":"P1","mvp":true,"path":"modules/acesso/acesso-perfis/f-autenticar-usuario.md","codigo":{"back":[],"front":[]}},{"id":"ACS-ACE-02","nome":"Consultar Perfil do Usuário","desc":"Consulta e resolve, no acesso do usuário, o seu perfil único e o conjunto de funcionalidades autorizadas que determinam o que ele pode fazer no sistema. ⚠️ *(derivado de AUTHZ/SSO — a confirmar)*","objeto":"**ALI: Usuário** · entidade principal (vínculo usuário↔UF; escopo dos administradores regionais; e-mail local) ⚠️ `CD_USUARIO` é a chave da identidade externa (SSO/AD) — não há tabela local de usuário; o vínculo por UF é o único dado de usuário persistido neste schema.","uso":"","estado":"rascunho","prioridade":"P1","mvp":true,"path":"modules/acesso/acesso-perfis/f-consultar-perfil-usuario.md","codigo":{"back":[],"front":[]}},{"id":"ACS-ACE-03","nome":"Vincular Usuário ao Sistema","desc":"Dá acesso à premiação, com o perfil Participante, a quem já tem conta no Sistema Indústria mas ainda não está habilitado nesta plataforma — evitando que a pessoa fique presa na mensagem de acesso não permitido ao tentar entrar pelo link público.","objeto":"**ALI: Usuário** · entidade principal (vínculo usuário↔UF; escopo dos administradores regionais; e-mail local) ⚠️ `CD_USUARIO` é a chave da identidade externa (SSO/AD) — não há tabela local de usuário; o vínculo por UF é o único dado de usuário persistido neste schema.","uso":"","estado":"rascunho","prioridade":"P1","mvp":true,"path":"modules/acesso/acesso-perfis/f-vincular-usuario-sistema.md","codigo":{"back":[],"front":[]}}]},{"nome":"Administradores Regionais","sigla":"ACS-ADM","desc":"Concentra o cadastro dos administradores regionais e o vínculo de cada um às UFs sob sua responsabilidade. O vínculo por UF define o escopo regional — quais inscrições o administrador enxerga e pode validar. A gestão é feita pelo Administrador Nacional.","path":"modules/acesso/administradores-regionais/README.md","feats":[{"id":"ACS-ADM-01","nome":"Pesquisar Administradores","desc":"Permite ao administrador nacional localizar administradores regionais por nome e por UF vinculada, listando-os para consulta, edição ou atribuição de escopo.","objeto":"**ALI: Usuário** · entidade principal (vínculo usuário↔UF; escopo dos administradores regionais; e-mail local) ⚠️ `CD_USUARIO` é a chave da identidade externa (SSO/AD) — não há tabela local de usuário; o vínculo por UF é o único dado de usuário persistido neste schema.","uso":"","estado":"rascunho","prioridade":"P1","mvp":true,"path":"modules/acesso/administradores-regionais/f-pesquisar-administrador.md","codigo":{"back":[],"front":[]}},{"id":"ACS-ADM-02","nome":"Cadastrar Administrador Regional","desc":"Permite ao administrador nacional cadastrar um usuário existente do login corporativo como administrador regional, deixando-o apto a receber UFs de escopo.","objeto":"**ALI: Usuário** · entidade principal (vínculo usuário↔UF; escopo dos administradores regionais; e-mail local) ⚠️ `CD_USUARIO` é a chave da identidade externa (SSO/AD) — não há tabela local de usuário; o vínculo por UF é o único dado de usuário persistido neste schema.","uso":"","estado":"rascunho","prioridade":"P1","mvp":true,"path":"modules/acesso/administradores-regionais/f-cadastrar-administrador-regional.md","codigo":{"back":[],"front":[]}},{"id":"ACS-ADM-03","nome":"Editar Administrador Regional","desc":"Permite ao administrador nacional alterar os dados editáveis de um administrador regional, como o e-mail de contato, mantendo o cadastro atualizado.","objeto":"**ALI: Usuário** · entidade principal (vínculo usuário↔UF; escopo dos administradores regionais; e-mail local) ⚠️ `CD_USUARIO` é a chave da identidade externa (SSO/AD) — não há tabela local de usuário; o vínculo por UF é o único dado de usuário persistido neste schema.","uso":"","estado":"rascunho","prioridade":"P2","mvp":false,"path":"modules/acesso/administradores-regionais/f-editar-administrador-regional.md","codigo":{"back":[],"front":[]}},{"id":"ACS-ADM-04","nome":"Vincular UF ao Administrador","desc":"Permite ao administrador nacional vincular uma ou mais UFs a um administrador regional, definindo o conjunto de inscrições que ele pode enxergar e validar.","objeto":"**ALI: Usuário** · entidade principal (vínculo usuário↔UF; escopo dos administradores regionais; e-mail local) ⚠️ `CD_USUARIO` é a chave da identidade externa (SSO/AD) — não há tabela local de usuário; o vínculo por UF é o único dado de usuário persistido neste schema.","uso":"","estado":"rascunho","prioridade":"P1","mvp":true,"path":"modules/acesso/administradores-regionais/f-vincular-uf-administrador.md","codigo":{"back":[],"front":[]}}]},{"nome":"Auditoria","sigla":"ACS-AUD","desc":"Reúne a consulta à trilha de auditoria do sistema — o registro append-only das ações críticas (quem fez, o que mudou e quando), alimentado por todos os domínios a cada validação, ajuste, avaliação ou configuração. ⚠️ *Feature Set sem HU dedicada — derivado do data-model (entidade Log de Auditoria); a confirmar.*","path":"modules/acesso/auditoria/README.md","feats":[{"id":"ACS-AUD-01","nome":"Consultar Trilha de Auditoria","desc":"","objeto":"**ALI: Log de Auditoria** · entidade técnica (append-only) ⚠️ ALI técnico não dimensionado no baseline APF (não consta nas 12 ALIs do baseline) — não soma PF.","uso":"","estado":"rascunho","prioridade":"P2","mvp":false,"path":"modules/acesso/auditoria/f-consultar-trilha-auditoria.md","codigo":{"back":[],"front":[]}}]}]},{"folder":"avaliacao","nome":"Avaliação","sigla":"AVL","desc":"Responde por toda a avaliação dos projetos — da configuração das etapas e da alocação de avaliadores ao registro de notas e pareceres, à apuração e à devolutiva. Mantém as alocações, as notas por questão, os pareceres, a apuração por etapa (média, classificação, desempate e fechamento por UF) e a devolutiva consolidada ao participante. É consumido pela Inscrição, cujo status de aprovação por etapa e cuja devolutiva refletem o resultado da avaliação.","path":"modules/avaliacao/README.md","fss":[{"nome":"Alocação de Avaliadores","sigla":"AVL-ALO","desc":"Define quem avalia quais inscrições em cada etapa, em duas camadas complementares: o pool de avaliadores por grupo (categoria × modalidade × tipo de participante) autoriza quem pode avaliar aquele grupo na etapa, e a alocação por inscrição designa os avaliadores específicos de cada inscrição elegível. Permite ainda cadastrar um novo avaliador sem sair do fluxo. A operação em cada etapa é restrita aos perfis autorizados pela capability daquela etapa e, para o Administrador Regional, às UFs vinculadas ao seu perfil.","path":"modules/avaliacao/alocacao/README.md","feats":[{"id":"AVL-ALO-01","nome":"Consultar Alocação de Avaliadores","desc":"Permite ao administrador consultar, por premiação e etapa, cada grupo de avaliação — categoria, modalidade, tipo de participante e submodalidade — com a quantidade de inscrições e o pool de avaliadores já autorizado, situando o trabalho de alocação daquela etapa.","objeto":"**ALI: Alocação Avaliadores** · entidade principal","uso":"","estado":"rascunho","prioridade":"P1","mvp":true,"path":"modules/avaliacao/alocacao/f-consultar-alocacao-avaliadores.md","codigo":{"back":[],"front":[]}},{"id":"AVL-ALO-02","nome":"Alocar Avaliador ao Grupo","desc":"Permite ao administrador compor e salvar o pool de avaliadores aptos a avaliar um grupo de categoria, modalidade, tipo de participante e submodalidade em uma etapa, servindo de base para a alocação por inscrição.","objeto":"**ALI: Alocação Avaliadores** · entidade principal","uso":"","estado":"rascunho","prioridade":"P1","mvp":true,"path":"modules/avaliacao/alocacao/f-alocar-avaliador-grupo.md","codigo":{"back":[],"front":[]}},{"id":"AVL-ALO-03","nome":"Cadastrar Avaliador","desc":"Permite ao administrador cadastrar, sem sair do fluxo de alocação, um novo avaliador no cadastro corporativo, já com o perfil Avaliador e as unidades regionais a que fica vinculado.","objeto":"**ALI: Usuário** · entidade principal (vínculo usuário↔UF; escopo dos administradores regionais; e-mail local) ⚠️ `CD_USUARIO` é a chave da identidade externa (SSO/AD) — não há tabela local de usuário; o vínculo por UF é o único dado de usuário persistido neste schema.","uso":"","estado":"rascunho","prioridade":"P1","mvp":true,"path":"modules/avaliacao/alocacao/f-cadastrar-avaliador.md","codigo":{"back":[],"front":[]}},{"id":"AVL-ALO-04","nome":"Alocar Avaliador à Inscrição","desc":"Permite ao administrador designar, a partir do pool do grupo, os avaliadores específicos de cada inscrição elegível de uma etapa, registrando a alocação de quem avaliará cada projeto.","objeto":"**ALI: Avaliação de Inscrição** · entidade principal","uso":"","estado":"rascunho","prioridade":"P1","mvp":true,"path":"modules/avaliacao/alocacao/f-alocar-avaliador-inscricao.md","codigo":{"back":[],"front":[]}},{"id":"AVL-ALO-05","nome":"Consultar Panorama do Avaliador","desc":"Mostra ao administrador quanto trabalho um avaliador já tem numa etapa — quantas avaliações estão alocadas, a iniciar, em andamento e finalizadas, separadas por grupo — para apoiar a decisão de alocar mais projetos a ele.","objeto":"**ALI: Avaliação de Inscrição** · entidade principal","uso":"","estado":"rascunho","prioridade":"P2","mvp":false,"path":"modules/avaliacao/alocacao/f-consultar-panorama-avaliador.md","codigo":{"back":[],"front":[]}},{"id":"AVL-ALO-06","nome":"Consultar Pendências de Alocação","desc":"Avisa o administrador de que existem participantes aprovados numa etapa já encerrada que ainda não têm avaliadores designados na etapa seguinte, e leva direto à tela onde a alocação pendente é resolvida.","objeto":"**ALI: Alocação Avaliadores** · entidade principal","uso":"","estado":"rascunho","prioridade":"P2","mvp":false,"path":"modules/avaliacao/alocacao/f-consultar-pendencias-alocacao.md","codigo":{"back":[],"front":[]}},{"id":"AVL-ALO-07","nome":"Exportar Relatório de Alocação","desc":"Entrega em planilha o retrato da alocação de uma etapa — quantos projetos cada avaliador recebeu e, nas etapas regionais, como a alocação se distribui por estado — para conferência e acompanhamento fora do sistema.","objeto":"**ALI: Alocação Avaliadores** · entidade principal","uso":"","estado":"rascunho","prioridade":"P2","mvp":false,"path":"modules/avaliacao/alocacao/f-exportar-relatorio-alocacao.md","codigo":{"back":[],"front":[]}}]},{"nome":"Apuração e Devolutiva","sigla":"AVL-APU","desc":"Fecha o ciclo de avaliação de cada etapa: apura a média ponderada e o ranking das inscrições que competem entre si, resolve empates persistentes por decisão manual registrada, retira da disputa a inscrição que não pode avançar, encerra a etapa por UF definindo quem avança e avisa o participante de que a devolutiva está disponível. Cuida também da devolutiva ao participante — gerada com apoio de Inteligência Artificial a partir dos pareceres e sempre revisada por uma pessoa antes de ser liberada — e do relatório de inscrições paradas que apoia a operação. Toda decisão de desempate e todo fechamento ficam registrados com responsável e justificativa.","path":"modules/avaliacao/apuracao-devolutiva/README.md","feats":[{"id":"AVL-APU-01","nome":"Apurar Resultado da Etapa","desc":"Permite ao administrador apurar o resultado de uma etapa: a média ponderada de cada inscrição, a colocação dentro de cada bloco de estado e grupo de disputa e os cortes de classificação e de premiação que a etapa aplica.","objeto":"**ALI: Avaliação de Inscrição** · entidade de suporte (apuração da inscrição por etapa: média, premiado, feedback consolidado, desclassificação)","uso":"","estado":"rascunho","prioridade":"P1","mvp":true,"path":"modules/avaliacao/apuracao-devolutiva/f-apurar-resultado-etapa.md","codigo":{"back":[],"front":[]}},{"id":"AVL-APU-02","nome":"Registrar Desempate","desc":"Permite ao administrador resolver o empate que atravessa a linha de corte de classificação ou a de premiação, comparando questão a questão as inscrições empatadas e elegendo a vencedora com justificativa e responsável registrados.","objeto":"**ALI: Avaliação de Inscrição** · entidade de suporte (decisões de desempate por etapa)","uso":"","estado":"rascunho","prioridade":"P1","mvp":true,"path":"modules/avaliacao/apuracao-devolutiva/f-registrar-desempate.md","codigo":{"back":[],"front":[]}},{"id":"AVL-APU-03","nome":"Encerrar Etapa por UF","desc":"Permite ao administrador encerrar oficialmente uma etapa em um estado, registrando responsável, data e observação, e consolidar as inscrições classificadas daquele estado, que são as que avançam para a etapa seguinte.","objeto":"**ALI: Avaliação de Inscrição** · entidade de suporte (fechamento de etapa por UF)","uso":"","estado":"rascunho","prioridade":"P1","mvp":true,"path":"modules/avaliacao/apuracao-devolutiva/f-encerrar-etapa-uf.md","codigo":{"back":[],"front":[]}},{"id":"AVL-APU-04","nome":"Gerar Devolutiva com IA","desc":"Permite ao administrador gerar, com apoio de Inteligência Artificial, uma sugestão de devolutiva a partir dos pareceres dos avaliadores finalizados, entregue ao editor para revisão humana.","objeto":"**ALI: Avaliação de Inscrição** · entidade de suporte (apuração da inscrição por etapa: média, premiado, feedback consolidado, desclassificação)","uso":"","estado":"rascunho","prioridade":"P2","mvp":false,"path":"modules/avaliacao/apuracao-devolutiva/f-gerar-devolutiva-ia.md","codigo":{"back":[],"front":[]}},{"id":"AVL-APU-05","nome":"Revisar Devolutiva","desc":"Permite ao administrador revisar e editar a devolutiva, tenha ela sido gerada por IA ou escrita à mão, e liberá-la ao participante respeitada a data de liberação da etapa.","objeto":"**ALI: Avaliação de Inscrição** · entidade de suporte (apuração da inscrição por etapa: média, premiado, feedback consolidado, desclassificação)","uso":"","estado":"rascunho","prioridade":"P1","mvp":true,"path":"modules/avaliacao/apuracao-devolutiva/f-revisar-devolutiva.md","codigo":{"back":[],"front":[]}},{"id":"AVL-APU-06","nome":"Gerar Relatório de Inscrições Paradas","desc":"Permite ao administrador gerar o relatório das inscrições paradas de uma premiação — as que estão Em Andamento ou Rascunho — segmentado por UF, status e tipo de participante, com o preenchimento de cada inscrição, disponível na tela e em planilha para uso fora do sistema.","objeto":"**ALI: Inscrição** · entidade principal","uso":"","estado":"rascunho","prioridade":"P2","mvp":false,"path":"modules/avaliacao/apuracao-devolutiva/f-gerar-relatorio-inscricoes-paradas.md","codigo":{"back":[],"front":[]}},{"id":"AVL-APU-08","nome":"Consultar Ranking da Etapa","desc":"Apresenta em tela própria, somente para leitura, o resultado já apurado de uma etapa — a colocação de cada inscrição dentro do seu bloco de disputa, a média e os selos de classificado e de premiado — para consulta depois do fechamento.","objeto":"**ALI: Avaliação de Inscrição** · entidade de suporte (apuração da inscrição por etapa: média, premiado, feedback consolidado, desclassificação)","uso":"","estado":"rascunho","prioridade":"P2","mvp":false,"path":"modules/avaliacao/apuracao-devolutiva/f-consultar-ranking-etapa.md","codigo":{"back":[],"front":[]}},{"id":"AVL-APU-09","nome":"Exportar Relatório da Etapa","desc":"Gera a planilha com o resultado completo de uma etapa — um resumo por estado e grupo e, para cada tipo de participante, a lista das inscrições com colocação, média, selos e as notas de cada avaliador — para uso fora do sistema.","objeto":"**ALI: Avaliação de Inscrição** · entidade de suporte (apuração da inscrição por etapa: média, premiado, feedback consolidado, desclassificação)","uso":"","estado":"rascunho","prioridade":"P2","mvp":false,"path":"modules/avaliacao/apuracao-devolutiva/f-exportar-relatorio-etapa.md","codigo":{"back":[],"front":[]}},{"id":"AVL-APU-10","nome":"Gerar Relatório de Inscrições","desc":"Apresenta ao administrador nacional todas as inscrições de uma premiação separadas por tipo de participante, com as respostas de cada uma, filtráveis por unidade federativa, categoria, modalidade, situação e período de início — em tela, com amostra de cada grupo, e em planilha, com o recorte completo.","objeto":"**ALI: Inscrição** · entidade principal","uso":"","estado":"rascunho","prioridade":"P2","mvp":false,"path":"modules/avaliacao/apuracao-devolutiva/f-gerar-relatorio-inscricoes.md","codigo":{"back":[],"front":[]}},{"id":"AVL-APU-12","nome":"Reabrir Etapa por UF","desc":"Permite ao administrador devolver à apuração um estado cuja etapa já foi encerrada, desfazendo o fechamento daquele escopo para que o corte de classificação e o de premiação sejam recalculados.","objeto":"**ALI: Avaliação de Inscrição** · entidade de suporte (fechamento de etapa por UF)","uso":"A reabertura parte do próprio bloco do estado na tela de fechamento da etapa, onde o estado já encerrado apresenta a ação de reabrir; ao confirmar, o estado volta a figurar como nunca fechado e a etapa, se estava encerrada, volta à situação Aberta.","estado":"rascunho","prioridade":"P1","mvp":false,"path":"modules/avaliacao/apuracao-devolutiva/f-reabrir-etapa-uf.md","codigo":{"back":[],"front":[]}},{"id":"AVL-APU-13","nome":"Desclassificar Inscrição na Etapa","desc":"Permite ao Administrador Nacional retirar uma inscrição da disputa de uma etapa, com justificativa registrada, para que ela não avance nem ocupe posição no resultado daquele estado — e devolvê-la à disputa enquanto o estado continuar aberto.","objeto":"**ALI: Avaliação de Inscrição** · entidade de suporte (apuração da inscrição por etapa: média, premiado, feedback consolidado, desclassificação)","uso":"A desclassificação é um **estado binário reversível**: a mesma linha do ranking oferece a ação de desclassificar quando a inscrição está em disputa e a de reverter quando está desclassificada. Por isso as duas vivem nesta feature, como par de alternância — ver `engine/FEATURE-DEFINITION.md`, *Pares de alternância (toggle)*.","estado":"rascunho","prioridade":"P1","mvp":false,"path":"modules/avaliacao/apuracao-devolutiva/f-desclassificar-inscricao-etapa.md","codigo":{"back":[],"front":[]}},{"id":"AVL-APU-14","nome":"Enviar Feedback ao Participante","desc":"Permite ao Administrador Nacional avisar por e-mail os participantes de uma etapa encerrada de que a devolutiva já está disponível, conferindo antes quem vai receber e acompanhando depois o que foi enviado.","objeto":"**ALI: Auditoria de E-mails** · entidade de suporte (lotes de envio do feedback da etapa) — o ALI é do domínio Validação; ver `global/data-models/validacao.md`","uso":"Até aqui a devolutiva ficava à espera de o participante voltar ao sistema e procurá-la: a liberação era um estado que ele tinha de ir conferir. O envio fecha essa lacuna sem automatizar nada — quem decide o momento é o administrador, e o e-mail leva o participante de volta ao sistema, onde a devolutiva é lida com o contexto da etapa.","estado":"rascunho","prioridade":"P1","mvp":false,"path":"modules/avaliacao/apuracao-devolutiva/f-enviar-feedback-participante.md","codigo":{"back":[],"front":[]}}]},{"nome":"Avaliação de Projetos","sigla":"AVL-AVA","desc":"É o espaço de trabalho do avaliador: aceitar o termo de confidencialidade da premiação, acompanhar as inscrições que lhe foram alocadas, atribuir nota por questão e registrar o parecer, e finalizar a avaliação. A avaliação é sigilosa (aceite de termo obrigatório e ocultação da identidade do participante quando a edição é confidencial) e independente — um avaliador nunca vê as notas dos demais. Inclui a ação administrativa de reabrir uma avaliação já finalizada quando é preciso devolver o trabalho ao avaliador.","path":"modules/avaliacao/avaliacao-projetos/README.md","feats":[{"id":"AVL-AVA-01","nome":"Acompanhar Minhas Avaliações","desc":"Permite ao avaliador acompanhar, em uma tela própria, todas as inscrições que lhe foram alocadas, com indicadores de andamento, prazos e seleção por premiação, etapa e status.","objeto":"**ALI: Avaliação de Inscrição** · entidade principal","uso":"","estado":"rascunho","prioridade":"P1","mvp":true,"path":"modules/avaliacao/avaliacao-projetos/f-acompanhar-minhas-avaliacoes.md","codigo":{"back":[],"front":[]}},{"id":"AVL-AVA-02","nome":"Aceitar Termo de Confidencialidade","desc":"Permite ao avaliador ler e aceitar o termo de confidencialidade de uma premiação, liberando o acesso aos dados dos participantes; o aceite é registrado uma única vez por avaliador e premiação.","objeto":"**ALI: Avaliação de Inscrição** · entidade de suporte (aceites do termo pelos avaliadores)","uso":"","estado":"rascunho","prioridade":"P1","mvp":true,"path":"modules/avaliacao/avaliacao-projetos/f-aceitar-termo-confidencialidade.md","codigo":{"back":[],"front":[]}},{"id":"AVL-AVA-03","nome":"Avaliar Inscrição","desc":"Permite ao avaliador atribuir a nota de 1 a 5 de cada questão do questionário e registrar o parecer individual da inscrição que lhe foi designada, salvando a pontuação progressivamente.","objeto":"**ALI: Avaliação de Inscrição** · entidade principal","uso":"","estado":"rascunho","prioridade":"P1","mvp":true,"path":"modules/avaliacao/avaliacao-projetos/f-avaliar-inscricao.md","codigo":{"back":[],"front":[]}},{"id":"AVL-AVA-04","nome":"Finalizar Avaliação","desc":"Permite ao avaliador finalizar a avaliação depois de pontuar todas as questões e registrar o parecer, encerrando o registro em modo somente leitura e abrindo em seguida a próxima avaliação pendente da sua fila.","objeto":"**ALI: Avaliação de Inscrição** · entidade principal","uso":"","estado":"rascunho","prioridade":"P1","mvp":true,"path":"modules/avaliacao/avaliacao-projetos/f-finalizar-avaliacao.md","codigo":{"back":[],"front":[]}},{"id":"AVL-AVA-05","nome":"Reabrir Avaliação","desc":"Permite ao Administrador Nacional reabrir uma avaliação já finalizada, revertendo-a para Em andamento e preservando as notas registradas, para devolver o trabalho ao avaliador.","objeto":"**ALI: Avaliação de Inscrição** · entidade principal","uso":"","estado":"rascunho","prioridade":"P2","mvp":false,"path":"modules/avaliacao/avaliacao-projetos/f-reabrir-avaliacao.md","codigo":{"back":[],"front":[]}},{"id":"AVL-AVA-06","nome":"Consultar Outros Avaliadores","desc":"Mostra ao avaliador quantas outras pessoas avaliam o mesmo projeto na mesma etapa e em que pé está cada uma, sem revelar quem são nem que notas atribuíram.","objeto":"**ALI: Avaliação de Inscrição** · entidade principal","uso":"","estado":"rascunho","prioridade":"P2","mvp":false,"path":"modules/avaliacao/avaliacao-projetos/f-consultar-outros-avaliadores.md","codigo":{"back":[],"front":[]}},{"id":"AVL-AVA-07","nome":"Consultar Premiações do Avaliador","desc":"Apresenta ao avaliador, logo ao entrar, as premiações em que ele tem projetos para avaliar, com quanto já avançou em cada uma e o aviso de qual delas ainda exige o aceite do termo de confidencialidade.","objeto":"**ALI: Alocação Avaliadores** · entidade principal","uso":"","estado":"rascunho","prioridade":"P1","mvp":true,"path":"modules/avaliacao/avaliacao-projetos/f-consultar-premiacoes-avaliador.md","codigo":{"back":[],"front":[]}}]},{"nome":"Etapas e Configuração da Avaliação","sigla":"AVL-ETA","desc":"Concentra a montagem do subsistema de avaliação de uma edição: o modo de avaliação (confidencial ou aberta, exibição da média de etapas anteriores e quantidade de avaliadores por inscrição), as etapas eliminatórias sequenciais (até cinco, com ordem, período e perfis autorizados a operá-las), os critérios automáticos de desempate por tipo de participante e o termo de confidencialidade exigido do avaliador. É a porta de entrada da avaliação: define o ritmo da premiação, quem opera cada fase e como a aprovação avança em cascata.","path":"modules/avaliacao/etapas-configuracao/README.md","feats":[{"id":"AVL-ETA-01","nome":"Configurar Avaliação","desc":"Permite ao administrador definir o modo de avaliação da edição — confidencial ou aberta —, habilitar a exibição da média de etapas anteriores ao avaliador e fixar a quantidade de avaliadores por inscrição, valores que valem para toda a premiação.","objeto":"**ALI: Premiação** · entidade principal","uso":"","estado":"rascunho","prioridade":"P1","mvp":true,"path":"modules/avaliacao/etapas-configuracao/f-configurar-avaliacao.md","codigo":{"back":[],"front":[]}},{"id":"AVL-ETA-02","nome":"Cadastrar Etapa","desc":"Permite ao administrador criar uma etapa eliminatória de avaliação com nome, período, perfis autorizados e os cortes de classificação e de premiação que ela aplica, posicionando-a ao final da sequência da premiação.","objeto":"**ALI: Premiação** · entidade de suporte (etapas/fases da premiação)","uso":"","estado":"rascunho","prioridade":"P1","mvp":true,"path":"modules/avaliacao/etapas-configuracao/f-cadastrar-etapa.md","codigo":{"back":[],"front":[]}},{"id":"AVL-ETA-03","nome":"Editar Etapa","desc":"Permite ao administrador alterar o nome, o período, os perfis autorizados e os cortes de classificação e de premiação de uma etapa ainda aberta, sem mover a sua posição na sequência da premiação.","objeto":"**ALI: Premiação** · entidade de suporte (etapas/fases da premiação)","uso":"","estado":"rascunho","prioridade":"P1","mvp":true,"path":"modules/avaliacao/etapas-configuracao/f-editar-etapa.md","codigo":{"back":[],"front":[]}},{"id":"AVL-ETA-04","nome":"Excluir Etapa","desc":"Permite ao administrador remover uma etapa da premiação quando não há avaliadores alocados nela, preservando o histórico por exclusão lógica.","objeto":"**ALI: Premiação** · entidade de suporte (etapas/fases da premiação)","uso":"","estado":"rascunho","prioridade":"P2","mvp":false,"path":"modules/avaliacao/etapas-configuracao/f-excluir-etapa.md","codigo":{"back":[],"front":[]}},{"id":"AVL-ETA-05","nome":"Reordenar Etapas","desc":"Permite ao administrador alterar a ordem relativa das etapas da premiação enquanto nenhuma delas estiver fechada, mantendo a numeração sequencial sem lacunas.","objeto":"**ALI: Premiação** · entidade de suporte (etapas/fases da premiação)","uso":"","estado":"rascunho","prioridade":"P2","mvp":false,"path":"modules/avaliacao/etapas-configuracao/f-reordenar-etapa.md","codigo":{"back":[],"front":[]}},{"id":"AVL-ETA-06","nome":"Configurar Critérios de Desempate","desc":"Permite ao Administrador Nacional definir, por tipo de participante, a lista ordenada de questões que o sistema aplica para quebrar empates de média no ranking, seguindo o modelo lexicográfico.","objeto":"**ALI: Avaliação de Inscrição** · entidade de suporte (critérios de desempate da premiação)","uso":"","estado":"rascunho","prioridade":"P1","mvp":true,"path":"modules/avaliacao/etapas-configuracao/f-configurar-criterios-desempate.md","codigo":{"back":[],"front":[]}},{"id":"AVL-ETA-07","nome":"Configurar Termo de Confidencialidade","desc":"Permite ao administrador cadastrar, substituir ou desativar o termo de confidencialidade — em texto ou arquivo — exigido do avaliador na premiação.","objeto":"**ALI: Avaliação de Inscrição** · entidade de suporte (termo de confidencialidade do avaliador)","uso":"","estado":"rascunho","prioridade":"P2","mvp":false,"path":"modules/avaliacao/etapas-configuracao/f-configurar-termo-confidencialidade.md","codigo":{"back":[],"front":[]}}]},{"nome":"Painel Administrativo de Avaliações","sigla":"AVL-PAI","desc":"Dá ao administrador a visão consolidada das avaliações em andamento e o espaço para transformar os pareceres individuais dos avaliadores em um único feedback consolidado — a voz oficial da banca — divulgado ao participante. Apresenta uma árvore por inscrição × etapa com indicadores e filtros, o detalhe com as notas por questão e o parecer de cada avaliador (auditáveis), e o editor de consolidação. A consolidação só é liberada depois que todos os avaliadores alocados finalizam. O acompanhamento é recortável por estado (UF) — com o Administrador Regional restrito às suas UFs — e mostra o andamento da consolidação de cada estado; fechado o estado na etapa, o feedback consolidado das suas inscrições deixa de ser alterável. A confidencialidade da edição não se aplica ao administrador, que enxerga todos os dados.","path":"modules/avaliacao/painel-administrativo/README.md","feats":[{"id":"AVL-PAI-01","nome":"Acompanhar Painel de Avaliações","desc":"Permite ao administrador acompanhar as avaliações em andamento da premiação, organizadas por inscrição e etapa e recortáveis por estado, com indicadores agregados, busca e o andamento da consolidação de cada estado, para saber o que já pode ser consolidado e quais estados ainda faltam.","objeto":"**ALI: Avaliação de Inscrição** · entidade de suporte (apuração da inscrição por etapa: média, premiado, feedback consolidado, desclassificação)","uso":"","estado":"rascunho","prioridade":"P1","mvp":true,"path":"modules/avaliacao/painel-administrativo/f-acompanhar-painel-avaliacoes.md","codigo":{"back":[],"front":[]}},{"id":"AVL-PAI-02","nome":"Consultar Avaliações por Etapa","desc":"Permite ao administrador consultar o detalhe de uma inscrição em uma etapa, reunindo os avaliadores alocados, o parecer individual de cada um e as notas por questão, como base para a consolidação.","objeto":"**ALI: Avaliação de Inscrição** · entidade principal","uso":"","estado":"rascunho","prioridade":"P1","mvp":true,"path":"modules/avaliacao/painel-administrativo/f-consultar-avaliacoes-etapa.md","codigo":{"back":[],"front":[]}},{"id":"AVL-PAI-03","nome":"Consolidar Avaliação","desc":"Permite ao administrador consolidar os pareceres dos avaliadores de uma inscrição em uma etapa num único texto oficial da banca, que passa a ser divulgado ao participante e se torna definitivo quando o estado da inscrição é fechado na etapa.","objeto":"**ALI: Avaliação de Inscrição** · entidade de suporte (apuração da inscrição por etapa: média, premiado, feedback consolidado, desclassificação)","uso":"","estado":"rascunho","prioridade":"P1","mvp":true,"path":"modules/avaliacao/painel-administrativo/f-consolidar-avaliacao.md","codigo":{"back":[],"front":[]}},{"id":"AVL-PAI-04","nome":"Exportar Relatório de Avaliadores","desc":"Entrega em planilha o acompanhamento das avaliações por avaliador — quantas cada um tem alocadas, a iniciar, em andamento e finalizadas, e a lista de avaliações que sustenta esses números — para cobrança e acompanhamento fora do sistema.","objeto":"**ALI: Avaliação de Inscrição** · entidade principal","uso":"","estado":"rascunho","prioridade":"P2","mvp":false,"path":"modules/avaliacao/painel-administrativo/f-exportar-relatorio-avaliadores.md","codigo":{"back":[],"front":[]}}]}]},{"folder":"configuracao","nome":"Configuração da Premiação","sigla":"CFG","desc":"Responde por toda a montagem e a parametrização de uma edição da premiação, sendo a fonte única da estrutura que as demais áreas consomem: categorias, modalidades, tipos de participante e suas ofertas, formulários de inscrição, questionários de avaliação, etapas, modelos de e-mail e critérios de avaliação. Mantém essa estrutura de forma reaproveitável entre edições, categorias e modalidades. É consumido por Inscrição, Validação e Avaliação sempre que precisam da estrutura da edição vigente.","path":"modules/configuracao/README.md","fss":[{"nome":"Categorias","sigla":"CFG-CAT","desc":"Concentra o cadastro e a manutenção das categorias da premiação — o segundo nível da estrutura, que agrupa modalidades dentro de uma edição. A categoria pode ser criada no catálogo administrativo (reutilizável entre edições) ou pela criação rápida na árvore de configuração do prêmio.","path":"modules/configuracao/categorias/README.md","feats":[{"id":"CFG-CAT-01","nome":"Pesquisar Categorias","desc":"Permite ao administrador localizar categorias do catálogo por nome e situação, listando os resultados para consulta, edição ou vínculo a um prêmio.","objeto":"**ALI: Categoria** · entidade principal","uso":"","estado":"rascunho","prioridade":"P1","mvp":true,"path":"modules/configuracao/categorias/f-pesquisar-categoria.md","codigo":{"back":[],"front":[]}},{"id":"CFG-CAT-02","nome":"Cadastrar Categoria","desc":"Permite ao administrador registrar uma nova categoria informando nome e descrição, deixando-a disponível no catálogo para ser vinculada a prêmios.","objeto":"**ALI: Categoria** · entidade principal","uso":"","estado":"rascunho","prioridade":"P1","mvp":true,"path":"modules/configuracao/categorias/f-cadastrar-categoria.md","codigo":{"back":[],"front":[]}},{"id":"CFG-CAT-03","nome":"Editar Categoria","desc":"Permite ao administrador alterar o nome e a descrição de uma categoria já cadastrada, mantendo o catálogo da premiação atualizado.","objeto":"**ALI: Categoria** · entidade principal","uso":"","estado":"rascunho","prioridade":"P1","mvp":true,"path":"modules/configuracao/categorias/f-editar-categoria.md","codigo":{"back":[],"front":[]}},{"id":"CFG-CAT-04","nome":"Visualizar Categoria","desc":"Permite ao administrador consultar os dados de uma categoria e a lista de prêmios aos quais ela está vinculada, com a situação de cada vínculo.","objeto":"**ALI: Categoria** · entidade principal","uso":"","estado":"rascunho","prioridade":"P2","mvp":false,"path":"modules/configuracao/categorias/f-visualizar-categoria.md","codigo":{"back":[],"front":[]}},{"id":"CFG-CAT-05","nome":"Ativar/Inativar Categoria","desc":"Permite ao administrador alternar a situação ativa/inativa de uma categoria (exclusão lógica), controlando sua oferta nos fluxos de inscrição sem removê-la do sistema.","objeto":"**ALI: Categoria** · entidade principal","uso":"","estado":"rascunho","prioridade":"P2","mvp":false,"path":"modules/configuracao/categorias/f-ativar-inativar-categoria.md","codigo":{"back":[],"front":[]}}]},{"nome":"Modelos de E-mail","sigla":"CFG-EMA","desc":"Configura os modelos de e-mail transacional de cada edição — os cinco tipos disparados pelo sistema: ajuste solicitado, inscrição aprovada, inscrição rejeitada, devolução ao administrador e **feedback disponível**. O administrador personaliza o assunto e o corpo com placeholders, pré-visualiza o resultado e pode restaurar o modelo padrão do sistema.","path":"modules/configuracao/modelos-email/README.md","feats":[{"id":"CFG-EMA-01","nome":"Consultar Modelos de E-mail","desc":"Permite ao administrador consultar os cinco tipos de e-mail transacional da edição, cada um com sua severidade e situação, como ponto de partida para editar e pré-visualizar o modelo.","objeto":"**ALI: Premiação** · entidade de suporte (modelos de e-mail transacional)","uso":"","estado":"rascunho","prioridade":"P1","mvp":true,"path":"modules/configuracao/modelos-email/f-consultar-modelo-email.md","codigo":{"back":[],"front":[]}},{"id":"CFG-EMA-02","nome":"Editar Modelo de E-mail","desc":"Permite ao administrador editar o assunto e o corpo de um modelo de e-mail com marcadores dinâmicos, ou restaurar o modelo ao padrão do sistema.","objeto":"**ALI: Premiação** · entidade de suporte (modelos de e-mail transacional)","uso":"","estado":"rascunho","prioridade":"P1","mvp":true,"path":"modules/configuracao/modelos-email/f-editar-modelo-email.md","codigo":{"back":[],"front":[]}},{"id":"CFG-EMA-03","nome":"Visualizar E-mail","desc":"Permite ao administrador pré-visualizar o corpo do e-mail renderizado antes de salvar, conferindo o assunto e a aparência do modelo sem substituir os marcadores dinâmicos.","objeto":"**ALI: Premiação** · entidade de suporte (modelos de e-mail transacional)","uso":"","estado":"rascunho","prioridade":"P2","mvp":false,"path":"modules/configuracao/modelos-email/f-visualizar-email.md","codigo":{"back":[],"front":[]}}]},{"nome":"Listas do Sistema","sigla":"CFG-LIS","desc":"Mantém as listas de valores reutilizáveis (ex.: UFs do Brasil, gêneros) usadas como fonte de opções dos campos de seleção dos formulários dinâmicos de inscrição. Cada lista tem um código único, um nome e uma coleção de itens ordenados, com valor e texto exibido ao participante.","path":"modules/configuracao/listas-sistema/README.md","feats":[{"id":"CFG-LIS-01","nome":"Pesquisar Listas","desc":"Permite ao administrador localizar listas de valores por nome e por código, com paginação, para consulta, edição ou configuração de seus itens.","objeto":"**ALI: Listas do Sistema** · entidade principal","uso":"","estado":"rascunho","prioridade":"P1","mvp":true,"path":"modules/configuracao/listas-sistema/f-pesquisar-lista.md","codigo":{"back":[],"front":[]}},{"id":"CFG-LIS-02","nome":"Cadastrar Lista","desc":"Permite ao administrador registrar uma nova lista de valores informando nome e um código único, habilitando em seguida a configuração dos seus itens.","objeto":"**ALI: Listas do Sistema** · entidade principal","uso":"","estado":"rascunho","prioridade":"P1","mvp":true,"path":"modules/configuracao/listas-sistema/f-cadastrar-lista.md","codigo":{"back":[],"front":[]}},{"id":"CFG-LIS-03","nome":"Editar Lista","desc":"Permite ao administrador alterar o nome ou o código de uma lista já cadastrada, mantendo a fonte de opções dos formulários atualizada.","objeto":"**ALI: Listas do Sistema** · entidade principal","uso":"","estado":"rascunho","prioridade":"P1","mvp":true,"path":"modules/configuracao/listas-sistema/f-editar-lista.md","codigo":{"back":[],"front":[]}},{"id":"CFG-LIS-04","nome":"Excluir Lista","desc":"Permite ao administrador remover uma lista de valores por exclusão lógica, retirando-a da consulta e da oferta como fonte de opções sem apagá-la do sistema.","objeto":"**ALI: Listas do Sistema** · entidade principal","uso":"","estado":"rascunho","prioridade":"P2","mvp":false,"path":"modules/configuracao/listas-sistema/f-excluir-lista.md","codigo":{"back":[],"front":[]}},{"id":"CFG-LIS-05","nome":"Configurar Itens da Lista","desc":"Permite ao administrador manter os itens de uma lista — incluir, reordenar e remover pares de valor e texto — que compõem as opções oferecidas nos campos de seleção dos formulários.","objeto":"**ALI: Listas do Sistema** · entidade de suporte (itens da lista)","uso":"","estado":"rascunho","prioridade":"P1","mvp":true,"path":"modules/configuracao/listas-sistema/f-configurar-itens-lista.md","codigo":{"back":[],"front":[]}}]},{"nome":"Modalidades","sigla":"CFG-MOD","desc":"Concentra o cadastro e a manutenção das modalidades da premiação — o terceiro nível da estrutura, subordinado à categoria, que define as formas de participação. A modalidade tem período de inscrição próprio e link de regulamento, permitindo controle temporal independente das datas globais do prêmio.","path":"modules/configuracao/modalidades/README.md","feats":[{"id":"CFG-MOD-01","nome":"Pesquisar Modalidades","desc":"Permite ao administrador localizar modalidades do catálogo por nome e situação, listando os resultados para consulta, edição ou vínculo a uma categoria.","objeto":"**ALI: Modalidade** · entidade principal","uso":"","estado":"rascunho","prioridade":"P1","mvp":true,"path":"modules/configuracao/modalidades/f-pesquisar-modalidade.md","codigo":{"back":[],"front":[]}},{"id":"CFG-MOD-02","nome":"Cadastrar Modalidade","desc":"Permite ao administrador registrar uma nova modalidade sob uma categoria, com descrição, link de regulamento e período de inscrição próprio, deixando-a disponível como forma de participação.","objeto":"**ALI: Modalidade** · entidade principal","uso":"","estado":"rascunho","prioridade":"P1","mvp":true,"path":"modules/configuracao/modalidades/f-cadastrar-modalidade.md","codigo":{"back":[],"front":[]}},{"id":"CFG-MOD-03","nome":"Editar Modalidade","desc":"Permite ao administrador alterar o nome, a descrição, o link de regulamento e o período de inscrição de uma modalidade já cadastrada, sem mudá-la de categoria.","objeto":"**ALI: Modalidade** · entidade principal","uso":"","estado":"rascunho","prioridade":"P1","mvp":true,"path":"modules/configuracao/modalidades/f-editar-modalidade.md","codigo":{"back":[],"front":[]}},{"id":"CFG-MOD-04","nome":"Visualizar Modalidade","desc":"Permite ao administrador consultar os dados de uma modalidade e as categorias e prêmios a que ela está vinculada, com o período de inscrição próprio de cada vínculo.","objeto":"**ALI: Modalidade** · entidade principal","uso":"","estado":"rascunho","prioridade":"P2","mvp":false,"path":"modules/configuracao/modalidades/f-visualizar-modalidade.md","codigo":{"back":[],"front":[]}},{"id":"CFG-MOD-05","nome":"Ativar/Inativar Modalidade","desc":"Permite ao administrador alternar a situação ativa/inativa de uma modalidade (exclusão lógica) sem afetar os tipos de participante vinculados, controlando a oferta da forma de participação nos fluxos de inscrição.","objeto":"**ALI: Modalidade** · entidade principal","uso":"","estado":"rascunho","prioridade":"P2","mvp":false,"path":"modules/configuracao/modalidades/f-ativar-inativar-modalidade.md","codigo":{"back":[],"front":[]}}]},{"nome":"Prêmios","sigla":"CFG-PRE","desc":"Concentra a criação e a manutenção da edição da premiação — o nível-raiz da estrutura — com seus dados, identidade visual, links públicos de inscrição, termos de aceite e critérios de avaliação. Também reaproveita edições anteriores por exportação e importação de toda a hierarquia em planilha.","path":"modules/configuracao/premios/README.md","feats":[{"id":"CFG-PRE-01","nome":"Pesquisar Prêmios","desc":"Permite ao administrador localizar edições da premiação por nome e por período de datas, listando os resultados de forma paginada para consulta, configuração ou reaproveitamento.","objeto":"**ALI: Premiação** · entidade principal","uso":"","estado":"rascunho","prioridade":"P1","mvp":true,"path":"modules/configuracao/premios/f-pesquisar-premio.md","codigo":{"back":[],"front":[]}},{"id":"CFG-PRE-02","nome":"Cadastrar Prêmio","desc":"Permite ao administrador registrar uma nova edição da premiação com nome, descrição, período e banner, deixando-a em modo de edição para a configuração dos demais itens.","objeto":"**ALI: Premiação** · entidade principal","uso":"","estado":"rascunho","prioridade":"P1","mvp":true,"path":"modules/configuracao/premios/f-cadastrar-premio.md","codigo":{"back":[],"front":[]}},{"id":"CFG-PRE-03","nome":"Editar Prêmio","desc":"Permite ao administrador alterar os dados de uma edição já criada — nome, descrição, período e banner — mantendo a configuração da premiação atualizada.","objeto":"**ALI: Premiação** · entidade principal","uso":"","estado":"rascunho","prioridade":"P1","mvp":true,"path":"modules/configuracao/premios/f-editar-premio.md","codigo":{"back":[],"front":[]}},{"id":"CFG-PRE-04","nome":"Ativar/Inativar Prêmio","desc":"Permite ao administrador alternar a situação de uma edição entre ativa e inativa, retirando-a dos fluxos públicos sem inativar suas categorias, modalidades e tipos de participante.","objeto":"**ALI: Premiação** · entidade principal","uso":"","estado":"rascunho","prioridade":"P2","mvp":false,"path":"modules/configuracao/premios/f-ativar-inativar-premio.md","codigo":{"back":[],"front":[]}},{"id":"CFG-PRE-05","nome":"Exportar Prêmios","desc":"Permite ao administrador gerar uma planilha com toda a hierarquia de uma edição para reaproveitar a estrutura na criação de novas premiações.","objeto":"**ALI: Premiação** · entidade principal","uso":"","estado":"rascunho","prioridade":"P2","mvp":false,"path":"modules/configuracao/premios/f-exportar-premio.md","codigo":{"back":[],"front":[]}},{"id":"CFG-PRE-06","nome":"Importar Prêmios","desc":"Permite ao administrador criar uma nova edição a partir de uma planilha preenchida, apresentando o resumo das estruturas criadas ao final.","objeto":"**ALI: Premiação** · entidade principal","uso":"","estado":"rascunho","prioridade":"P2","mvp":false,"path":"modules/configuracao/premios/f-importar-premio.md","codigo":{"back":[],"front":[]}},{"id":"CFG-PRE-07","nome":"Gerar Link Público","desc":"Permite ao administrador emitir o link público de inscrição de um tipo de participante, disponibilizando o endereço para divulgação aos candidatos.","objeto":"**ALI: Premiação** · entidade de suporte (links públicos de inscrição)","uso":"","estado":"rascunho","prioridade":"P1","mvp":true,"path":"modules/configuracao/premios/f-gerar-link-publico.md","codigo":{"back":[],"front":[]}},{"id":"CFG-PRE-08","nome":"Consultar Links Públicos","desc":"Permite ao administrador visualizar os links públicos de inscrição já emitidos de uma edição, com o respectivo tipo de participante e endereço.","objeto":"**ALI: Premiação** · entidade de suporte (links públicos de inscrição)","uso":"","estado":"rascunho","prioridade":"P2","mvp":false,"path":"modules/configuracao/premios/f-consultar-link-publico.md","codigo":{"back":[],"front":[]}},{"id":"CFG-PRE-09","nome":"Cadastrar Termo de Aceite","desc":"Permite ao administrador registrar um termo de aceite da edição com título e texto, podendo marcá-lo como obrigatório para concluir a inscrição.","objeto":"**ALI: Premiação** · entidade de suporte (termos que o participante aceita)","uso":"","estado":"rascunho","prioridade":"P1","mvp":true,"path":"modules/configuracao/premios/f-cadastrar-termo-aceite.md","codigo":{"back":[],"front":[]}},{"id":"CFG-PRE-10","nome":"Editar Termo de Aceite","desc":"Permite ao administrador alterar o título, o texto ou a obrigatoriedade de um termo de aceite já registrado na edição.","objeto":"**ALI: Premiação** · entidade de suporte (termos que o participante aceita)","uso":"","estado":"rascunho","prioridade":"P2","mvp":false,"path":"modules/configuracao/premios/f-editar-termo-aceite.md","codigo":{"back":[],"front":[]}},{"id":"CFG-PRE-11","nome":"Excluir Termo de Aceite","desc":"Permite ao administrador remover um termo de aceite da edição, deixando de exigi-lo dos participantes.","objeto":"**ALI: Premiação** · entidade de suporte (termos que o participante aceita)","uso":"","estado":"rascunho","prioridade":"P2","mvp":false,"path":"modules/configuracao/premios/f-excluir-termo-aceite.md","codigo":{"back":[],"front":[]}},{"id":"CFG-PRE-12","nome":"Configurar Critérios de Avaliação","desc":"","objeto":"**ALI: Premiação** · entidade de suporte (critérios de avaliação — ⚠️ configurados aqui, consumidos no módulo Avaliação)","uso":"","estado":"rascunho","prioridade":"P2","mvp":false,"path":"modules/configuracao/premios/f-configurar-criterios-avaliacao.md","codigo":{"back":[],"front":[]}},{"id":"CFG-PRE-13","nome":"Carregar Imagem de Configuração","desc":"Permite ao administrador subir as imagens que compõem a identidade visual da premiação — logotipo, banner e ícone — e obter o endereço público de cada uma, para uso na página de inscrição.","objeto":"**ALI: Premiação** · entidade de suporte (identidade visual)","uso":"","estado":"rascunho","prioridade":"P2","mvp":false,"path":"modules/configuracao/premios/f-carregar-imagem-configuracao.md","codigo":{"back":[],"front":[]}}]},{"nome":"Tipos de Participante","sigla":"CFG-TIP","desc":"Concentra o cadastro do tipo de participante — o quarto nível da estrutura, o mais rico em configuração — e de toda a sua estrutura de inscrição e avaliação: formulário dinâmico, campos, enquadramentos, anexos exigidos, questionário de avaliação e configuração de equipe. Cada tipo tem, no máximo, um formulário e um questionário vigentes.","path":"modules/configuracao/tipos-participante/README.md","feats":[{"id":"CFG-TIP-01","nome":"Pesquisar Tipos de Participante","desc":"Permite ao administrador localizar os tipos de participante por nome e situação, listando os resultados para consulta, configuração da estrutura de inscrição ou composição de ofertas.","objeto":"**ALI: Tipo de Participante** · entidade principal","uso":"","estado":"rascunho","prioridade":"P1","mvp":true,"path":"modules/configuracao/tipos-participante/f-pesquisar-tipo-participante.md","codigo":{"back":[],"front":[]}},{"id":"CFG-TIP-02","nome":"Cadastrar Tipo de Participante","desc":"Permite ao administrador registrar um novo tipo de participante, com nome e descrição e a opção de inscrição em equipe com tamanho mínimo e máximo de membros.","objeto":"**ALI: Tipo de Participante** · entidade principal","uso":"","estado":"rascunho","prioridade":"P1","mvp":true,"path":"modules/configuracao/tipos-participante/f-cadastrar-tipo-participante.md","codigo":{"back":[],"front":[]}},{"id":"CFG-TIP-03","nome":"Editar Tipo de Participante","desc":"Permite ao administrador alterar os dados gerais e as opções de inscrição em equipe de um tipo de participante já cadastrado, mantendo a estrutura da premiação atualizada.","objeto":"**ALI: Tipo de Participante** · entidade principal","uso":"","estado":"rascunho","prioridade":"P1","mvp":true,"path":"modules/configuracao/tipos-participante/f-editar-tipo-participante.md","codigo":{"back":[],"front":[]}},{"id":"CFG-TIP-04","nome":"Visualizar Tipo de Participante","desc":"Permite ao administrador consultar os dados de um tipo de participante, seus vínculos e o resumo dos recursos de inscrição e avaliação já configurados.","objeto":"**ALI: Tipo de Participante** · entidade principal","uso":"","estado":"rascunho","prioridade":"P2","mvp":false,"path":"modules/configuracao/tipos-participante/f-visualizar-tipo-participante.md","codigo":{"back":[],"front":[]}},{"id":"CFG-TIP-05","nome":"Ativar/Inativar Tipo de Participante","desc":"Permite ao administrador alternar a situação ativa/inativa de um tipo de participante (exclusão lógica), sem afetar as sub-configurações de inscrição e avaliação já montadas.","objeto":"**ALI: Tipo de Participante** · entidade principal","uso":"","estado":"rascunho","prioridade":"P2","mvp":false,"path":"modules/configuracao/tipos-participante/f-ativar-inativar-tipo-participante.md","codigo":{"back":[],"front":[]}},{"id":"CFG-TIP-06","nome":"Configurar Formulário de Inscrição","desc":"Permite ao administrador configurar o formulário de inscrição de um tipo de participante, escolhendo o modo de preenchimento em página única ou em etapas e organizando os campos e seções.","objeto":"**ALI: Tipo de Participante** · entidade de suporte (formulário de inscrição)","uso":"","estado":"rascunho","prioridade":"P1","mvp":true,"path":"modules/configuracao/tipos-participante/f-configurar-formulario.md","codigo":{"back":[],"front":[]}},{"id":"CFG-TIP-07","nome":"Cadastrar Campo","desc":"Permite ao administrador adicionar um campo tipado ao formulário de inscrição, definindo seu rótulo, tipo e regras de preenchimento.","objeto":"**ALI: Tipo de Participante** · entidade de suporte (campos do formulário dinâmico)","uso":"","estado":"rascunho","prioridade":"P1","mvp":true,"path":"modules/configuracao/tipos-participante/f-cadastrar-campo.md","codigo":{"back":[],"front":[]}},{"id":"CFG-TIP-08","nome":"Editar Campo","desc":"Permite ao administrador alterar o rótulo, a obrigatoriedade e as demais propriedades de um campo já existente no formulário de inscrição.","objeto":"**ALI: Tipo de Participante** · entidade de suporte (campos do formulário dinâmico)","uso":"","estado":"rascunho","prioridade":"P2","mvp":false,"path":"modules/configuracao/tipos-participante/f-editar-campo.md","codigo":{"back":[],"front":[]}},{"id":"CFG-TIP-09","nome":"Excluir Campo","desc":"Permite ao administrador excluir um campo do formulário de inscrição do tipo de participante — de forma definitiva quando o campo ainda não foi respondido, ou lógica quando já existem inscrições que o utilizaram, preservando o histórico.","objeto":"**ALI: Tipo de Participante** · entidade de suporte (campos do formulário dinâmico)","uso":"","estado":"rascunho","prioridade":"P2","mvp":false,"path":"modules/configuracao/tipos-participante/f-excluir-campo.md","codigo":{"back":[],"front":[]}},{"id":"CFG-TIP-10","nome":"Cadastrar Enquadramento","desc":"","objeto":"**ALI: Tipo de Participante** · entidade de suporte (enquadramentos)","uso":"","estado":"rascunho","prioridade":"P1","mvp":true,"path":"modules/configuracao/tipos-participante/f-cadastrar-enquadramento.md","codigo":{"back":[],"front":[]}},{"id":"CFG-TIP-11","nome":"Ativar/Inativar Enquadramento","desc":"","objeto":"**ALI: Tipo de Participante** · entidade de suporte (enquadramentos)","uso":"","estado":"rascunho","prioridade":"P2","mvp":false,"path":"modules/configuracao/tipos-participante/f-ativar-inativar-enquadramento.md","codigo":{"back":[],"front":[]}},{"id":"CFG-TIP-12","nome":"Configurar Anexos Exigidos","desc":"Permite ao administrador configurar os documentos que o candidato deve enviar na inscrição de um tipo de participante, definindo nome, obrigatoriedade, extensões aceitas e tamanho máximo de cada anexo.","objeto":"**ALI: Tipo de Participante** · entidade de suporte (config de anexos exigidos)","uso":"","estado":"rascunho","prioridade":"P1","mvp":true,"path":"modules/configuracao/tipos-participante/f-configurar-anexo.md","codigo":{"back":[],"front":[]}},{"id":"CFG-TIP-13","nome":"Cadastrar Questão","desc":"Permite ao administrador cadastrar uma questão — discursiva ou objetiva — no questionário de avaliação do tipo de participante, com enunciado e peso, para padronizar a pontuação das inscrições pelos avaliadores.","objeto":"**ALI: Tipo de Participante** · entidade de suporte (questões do questionário)","uso":"","estado":"rascunho","prioridade":"P1","mvp":true,"path":"modules/configuracao/tipos-participante/f-cadastrar-questao.md","codigo":{"back":[],"front":[]}},{"id":"CFG-TIP-14","nome":"Editar Questão","desc":"Permite ao administrador editar uma questão já cadastrada no questionário de avaliação — alterando enunciado, peso, alternativas, limite de caracteres e posição — para manter o questionário do tipo de participante atualizado.","objeto":"**ALI: Tipo de Participante** · entidade de suporte (questões do questionário)","uso":"","estado":"rascunho","prioridade":"P2","mvp":false,"path":"modules/configuracao/tipos-participante/f-editar-questao.md","codigo":{"back":[],"front":[]}},{"id":"CFG-TIP-15","nome":"Configurar Equipe","desc":"Permite ao administrador configurar a inscrição em equipe de um tipo de participante, definindo os tipos de vínculo dos membros (ex.: Líder, Membro) e os campos extras coletados por membro.","objeto":"**ALI: Tipo de Participante** · entidade de suporte (config de campos extras de membro de equipe)","uso":"","estado":"rascunho","prioridade":"P2","mvp":false,"path":"modules/configuracao/tipos-participante/f-configurar-equipe.md","codigo":{"back":[],"front":[]}},{"id":"CFG-TIP-16","nome":"Importar Configuração do Tipo de Participante","desc":"Permite ao administrador importar, a partir de uma planilha, a estrutura de inscrição e avaliação de um tipo de participante já existente, aproveitando uma configuração pronta de outra fonte em vez de montá-la do zero.","objeto":"**ALI: Tipo de Participante** · entidade principal","uso":"","estado":"rascunho","prioridade":"P3","mvp":false,"path":"modules/configuracao/tipos-participante/f-importar-configuracao.md","codigo":{"back":[],"front":[]}}]},{"nome":"Vínculos e Ofertas","sigla":"CFG-VIN","desc":"Monta a estrutura da edição cruzando tipo de participante × modalidade × categoria (a oferta) na árvore hierárquica do prêmio. Vincula e desvincula categorias, modalidades e tipos de participante — existentes no catálogo ou criados no mesmo passo —, duplica ramos inteiros para reaproveitamento e mantém as submodalidades (ofertas) da edição.","path":"modules/configuracao/ofertas/README.md","feats":[{"id":"CFG-VIN-01","nome":"Consultar Estrutura da Premiação","desc":"Permite ao administrador navegar a hierarquia de uma edição — Premiação, Categorias, Modalidades e Tipos de Participante — para consultar como a estrutura está montada e escolher o nó sobre o qual agir.","objeto":"**ALI: Tipo de Participante** · entidade de suporte (oferta: tipo×modalidade×categoria — permite equipe, min/max, slug)","uso":"","estado":"rascunho","prioridade":"P1","mvp":true,"path":"modules/configuracao/ofertas/f-consultar-estrutura-premiacao.md","codigo":{"back":[],"front":[]}},{"id":"CFG-VIN-02","nome":"Vincular Categoria","desc":"Permite ao administrador associar uma categoria do catálogo à edição do prêmio, ou registrar uma nova categoria e vinculá-la num único passo, montando o primeiro nível abaixo da premiação.","objeto":"**ALI: Categoria** · entidade de suporte (vínculo Premiação↔Categoria por edição)","uso":"","estado":"rascunho","prioridade":"P1","mvp":true,"path":"modules/configuracao/ofertas/f-vincular-categoria.md","codigo":{"back":[],"front":[]}},{"id":"CFG-VIN-03","nome":"Desvincular Categoria","desc":"Permite ao administrador desfazer o vínculo de uma categoria com a edição do prêmio por exclusão lógica, retirando-a da estrutura sem apagá-la do catálogo nem de outras edições.","objeto":"**ALI: Categoria** · entidade de suporte (vínculo Premiação↔Categoria por edição)","uso":"","estado":"rascunho","prioridade":"P2","mvp":false,"path":"modules/configuracao/ofertas/f-desvincular-categoria.md","codigo":{"back":[],"front":[]}},{"id":"CFG-VIN-04","nome":"Vincular Modalidade","desc":"Permite ao administrador associar uma modalidade a uma categoria já vinculada à edição, ou criar uma nova modalidade e vinculá-la, formando o segundo nível da estrutura do prêmio.","objeto":"**ALI: Modalidade** · entidade de suporte (vínculo Modalidade↔Categoria-da-premiação)","uso":"","estado":"rascunho","prioridade":"P1","mvp":true,"path":"modules/configuracao/ofertas/f-vincular-modalidade.md","codigo":{"back":[],"front":[]}},{"id":"CFG-VIN-05","nome":"Desvincular Modalidade","desc":"Permite ao administrador desfazer o vínculo de uma modalidade com uma categoria da edição por exclusão lógica, retirando aquele ramo sem remover a modalidade do catálogo.","objeto":"**ALI: Modalidade** · entidade de suporte (vínculo Modalidade↔Categoria-da-premiação)","uso":"","estado":"rascunho","prioridade":"P2","mvp":false,"path":"modules/configuracao/ofertas/f-desvincular-modalidade.md","codigo":{"back":[],"front":[]}},{"id":"CFG-VIN-06","nome":"Vincular Tipo de Participante","desc":"Permite ao administrador associar um tipo de participante a uma modalidade da estrutura, formando a oferta que o inscrito escolhe, ou criar o tipo e vinculá-lo no mesmo passo.","objeto":"**ALI: Tipo de Participante** · entidade de suporte (oferta: tipo×modalidade×categoria — permite equipe, min/max, slug)","uso":"","estado":"rascunho","prioridade":"P1","mvp":true,"path":"modules/configuracao/ofertas/f-vincular-tipo-participante.md","codigo":{"back":[],"front":[]}},{"id":"CFG-VIN-07","nome":"Desvincular Tipo de Participante","desc":"Permite ao administrador desfazer uma oferta ao remover, por exclusão lógica, o vínculo de um tipo de participante com uma modalidade, sem excluir o tipo do catálogo.","objeto":"**ALI: Tipo de Participante** · entidade de suporte (oferta: tipo×modalidade×categoria — permite equipe, min/max, slug)","uso":"","estado":"rascunho","prioridade":"P2","mvp":false,"path":"modules/configuracao/ofertas/f-desvincular-tipo-participante.md","codigo":{"back":[],"front":[]}},{"id":"CFG-VIN-08","nome":"Duplicar Oferta","desc":"Permite ao administrador duplicar um ramo da estrutura — categoria, modalidade ou oferta — copiando toda a subestrutura abaixo dele, para reaproveitar a montagem entre edições sem refazer nó a nó.","objeto":"**ALI: Tipo de Participante** · entidade de suporte (oferta: tipo×modalidade×categoria — permite equipe, min/max, slug)","uso":"","estado":"rascunho","prioridade":"P2","mvp":false,"path":"modules/configuracao/ofertas/f-duplicar-oferta.md","codigo":{"back":[],"front":[]}},{"id":"CFG-VIN-09","nome":"Cadastrar Submodalidade","desc":"","objeto":"**ALI: Tipo de Participante** · entidade de suporte (oferta: tipo×modalidade×categoria — permite equipe, min/max, slug)","uso":"","estado":"rascunho","prioridade":"P2","mvp":false,"path":"modules/configuracao/ofertas/f-cadastrar-submodalidade.md","codigo":{"back":[],"front":[]}},{"id":"CFG-VIN-10","nome":"Editar Submodalidade","desc":"","objeto":"**ALI: Tipo de Participante** · entidade de suporte (oferta: tipo×modalidade×categoria — permite equipe, min/max, slug)","uso":"","estado":"rascunho","prioridade":"P2","mvp":false,"path":"modules/configuracao/ofertas/f-editar-submodalidade.md","codigo":{"back":[],"front":[]}},{"id":"CFG-VIN-11","nome":"Ativar/Inativar Submodalidade","desc":"","objeto":"**ALI: Tipo de Participante** · entidade de suporte (oferta: tipo×modalidade×categoria — permite equipe, min/max, slug)","uso":"","estado":"rascunho","prioridade":"P2","mvp":false,"path":"modules/configuracao/ofertas/f-ativar-inativar-submodalidade.md","codigo":{"back":[],"front":[]}}]}]},{"folder":"inscricao","nome":"Inscrição","sigla":"INS","desc":"Responde por toda a jornada de inscrição do participante, do acesso pelo link público à finalização, sendo a fonte única das inscrições e do seu andamento. Mantém as respostas ao formulário e ao questionário, os documentos anexados, a composição da equipe, os aceites de termos e o histórico de cada inscrição. É consumido por Validação e Avaliação, que conferem e avaliam as inscrições enviadas, e pelo próprio participante, que acompanha o status e recebe a devolutiva.","path":"modules/inscricao/README.md","fss":[{"nome":"Acompanhamento","sigla":"INS-ACO","desc":"Reúne o painel do participante para acompanhar as suas inscrições e a avaliação recebida. Apresenta a visão consolidada de cada inscrição — estatísticas e status atual — e dá acesso à devolutiva liberada após a avaliação, cumprindo a transparência ponta a ponta prometida ao inscrito.","path":"modules/inscricao/acompanhamento/README.md","feats":[{"id":"INS-ACO-01","nome":"Acompanhar Inscrição","desc":"Permite ao participante acompanhar as próprias inscrições em um painel com indicadores e a situação atual de cada uma, com acesso à ação correspondente ao andamento.","objeto":"**ALI: Inscrição** · entidade principal","uso":"","estado":"rascunho","prioridade":"P1","mvp":true,"path":"modules/inscricao/acompanhamento/f-acompanhar-inscricao.md","codigo":{"back":[],"front":[]}},{"id":"INS-ACO-02","nome":"Visualizar Devolutiva","desc":"Permite ao participante ler a devolutiva consolidada da avaliação de uma inscrição em cada etapa avaliada, a partir do momento em que aquela etapa a libera.","objeto":"**ALI: Inscrição** · entidade principal","uso":"","estado":"rascunho","prioridade":"P2","mvp":false,"path":"modules/inscricao/acompanhamento/f-visualizar-devolutiva.md","codigo":{"back":[],"front":[]}}]},{"nome":"Notificações","sigla":"INS-NOT","desc":"Entrega ao participante os avisos in-app sobre o andamento da sua inscrição — solicitação de ajuste, aprovação, rejeição, reenvio e disponibilidade da devolutiva. Apresenta o painel lateral com as últimas notificações e a contagem de não lidas no sino, e permite marcar cada aviso como lido.","path":"modules/inscricao/notificacoes/README.md","feats":[{"id":"INS-NOT-01","nome":"Consultar Notificações","desc":"Permite ao participante consultar as próprias notificações sobre o andamento da inscrição e ver quantas ainda não foram lidas.","objeto":"**ALI: Notificação Participante** · entidade principal","uso":"","estado":"rascunho","prioridade":"P1","mvp":true,"path":"modules/inscricao/notificacoes/f-consultar-notificacao.md","codigo":{"back":[],"front":[]}},{"id":"INS-NOT-02","nome":"Marcar Notificação como Lida","desc":"Permite ao participante marcar uma notificação como lida, atualizando a contagem de avisos ainda não lidos.","objeto":"**ALI: Notificação Participante** · entidade principal","uso":"","estado":"rascunho","prioridade":"P2","mvp":false,"path":"modules/inscricao/notificacoes/f-marcar-notificacao-lida.md","codigo":{"back":[],"front":[]}}]},{"nome":"Inscrição do Participante","sigla":"INS-PAR","desc":"Concentra a jornada de inscrição do participante no Prêmio, do acesso ao link público até o envio para validação: iniciar o rascunho, preencher o formulário dinâmico e o questionário, enviar documentos, cadastrar a equipe, aceitar os termos e finalizar — sempre com salvamento automático e a possibilidade de salvar e retomar o trabalho. Quando a Validação solicita ajustes, o participante corrige os itens apontados e reenvia a inscrição.","path":"modules/inscricao/inscricao-participante/README.md","feats":[{"id":"INS-PAR-01","nome":"Cadastrar Inscrição","desc":"Permite ao participante iniciar uma nova inscrição em rascunho pelo link público da premiação, criando o registro de trabalho onde o preenchimento terá continuidade.","objeto":"**ALI: Inscrição** · entidade principal","uso":"","estado":"rascunho","prioridade":"P1","mvp":true,"path":"modules/inscricao/inscricao-participante/f-cadastrar-inscricao.md","codigo":{"back":[],"front":[]}},{"id":"INS-PAR-02","nome":"Editar Inscrição","desc":"Permite ao participante preencher e alterar os dados da inscrição em andamento — oferta, campos do formulário dinâmico, respostas do questionário e membros da equipe — com salvamento automático a cada alteração.","objeto":"**ALI: Inscrição** · entidade principal","uso":"","estado":"rascunho","prioridade":"P1","mvp":true,"path":"modules/inscricao/inscricao-participante/f-editar-inscricao.md","codigo":{"back":[],"front":[]}},{"id":"INS-PAR-03","nome":"Finalizar Inscrição","desc":"Permite ao participante submeter a inscrição para validação após a checagem dos itens obrigatórios, gerando o número de protocolo que identifica a inscrição enviada.","objeto":"**ALI: Inscrição** · entidade principal","uso":"","estado":"rascunho","prioridade":"P1","mvp":true,"path":"modules/inscricao/inscricao-participante/f-finalizar-inscricao.md","codigo":{"back":[],"front":[]}},{"id":"INS-PAR-04","nome":"Reenviar Inscrição","desc":"Permite ao participante reenviar para validação uma inscrição que teve ajustes solicitados, depois de corrigidos os itens apontados pela análise regional.","objeto":"**ALI: Inscrição** · entidade principal","uso":"","estado":"rascunho","prioridade":"P2","mvp":false,"path":"modules/inscricao/inscricao-participante/f-reenviar-inscricao.md","codigo":{"back":[],"front":[]}},{"id":"INS-PAR-05","nome":"Anexar Documento","desc":"Permite ao participante enviar os documentos obrigatórios e opcionais exigidos pela configuração de anexos da premiação, vinculando cada arquivo à inscrição.","objeto":"**ALI: Inscrição** · entidade de suporte (documentos anexados à inscrição)","uso":"","estado":"rascunho","prioridade":"P1","mvp":true,"path":"modules/inscricao/inscricao-participante/f-anexar-documento.md","codigo":{"back":[],"front":[]}},{"id":"INS-PAR-06","nome":"Aceitar Termo","desc":"Permite ao participante registrar o aceite dos termos obrigatórios e opcionais da premiação, condição necessária para concluir a inscrição.","objeto":"**ALI: Inscrição** · entidade de suporte (aceites de termos vinculados à inscrição)","uso":"","estado":"rascunho","prioridade":"P1","mvp":true,"path":"modules/inscricao/inscricao-participante/f-aceitar-termo.md","codigo":{"back":[],"front":[]}},{"id":"INS-PAR-07","nome":"Retomar Inscrição","desc":"Permite ao participante reabrir um rascunho salvo e retomar o preenchimento da inscrição do ponto em que havia parado.","objeto":"**ALI: Inscrição** · entidade de suporte (log de autosave; sem os 6 campos globais — tabela de log)","uso":"","estado":"rascunho","prioridade":"P2","mvp":false,"path":"modules/inscricao/inscricao-participante/f-retomar-inscricao.md","codigo":{"back":[],"front":[]}},{"id":"INS-PAR-08","nome":"Registrar Pré-cadastro","desc":"Permite a quem chega pelo link público informar nome e e-mail para obter acesso ao Sistema Indústria e já ter a inscrição daquela oferta criada, sem depender de um cadastro prévio.","objeto":"**ALI: Inscrição** · entidade principal","uso":"","estado":"rascunho","prioridade":"P1","mvp":true,"path":"modules/inscricao/inscricao-participante/f-registrar-pre-cadastro.md","codigo":{"back":[],"front":[]}}]}]},{"folder":"validacao","nome":"Validação","sigla":"VAL","desc":"Responde pela conferência e pela decisão sobre as inscrições recebidas em cada UF, garantindo que apenas inscrições válidas avancem para a avaliação. Mantém o parecer de validação, as solicitações de ajuste ao participante e a auditoria das rodadas de ajuste. É consumido pela Avaliação, que recebe as inscrições aprovadas, e apoia-se no vínculo regional do administrador definido em Acesso e Gestão.","path":"modules/validacao/README.md","fss":[{"nome":"Ajustes da Inscrição","sigla":"VAL-AJU","desc":"Trata do ciclo de ajustes da inscrição durante a validação: o administrador solicita correções ao participante e, quando a inscrição retorna, audita por rodada o que foi efetivamente alterado. Preserva o histórico de cada rodada — o que foi solicitado e o que mudou entre a solicitação e o reenvio — e permite exportar essa auditoria como evidência documental.","path":"modules/validacao/ajustes/README.md","feats":[{"id":"VAL-AJU-01","nome":"Solicitar Ajuste","desc":"Permite ao validador solicitar ao participante correções na inscrição em validação, reunindo de um a dez itens de ajuste e movendo a inscrição para a situação Aguardando Ajuste.","objeto":"**ALI: Inscrição** · entidade de suporte (itens de ajuste solicitado ⚠️ — vinculados ao histórico; consumidos pela Validação)","uso":"","estado":"rascunho","prioridade":"P1","mvp":true,"path":"modules/validacao/ajustes/f-solicitar-ajuste.md","codigo":{"back":[],"front":[]}},{"id":"VAL-AJU-02","nome":"Consultar Auditoria de Ajustes","desc":"Permite ao validador consultar, por rodada de ajuste, o que o participante alterou entre a solicitação e o reenvio da inscrição, agrupado por respostas, documentos e equipe.","objeto":"**ALI: Inscrição** · entidade de suporte (snapshots de estado da inscrição por rodada/etapa)","uso":"","estado":"rascunho","prioridade":"P2","mvp":false,"path":"modules/validacao/ajustes/f-consultar-auditoria-ajustes.md","codigo":{"back":[],"front":[]}},{"id":"VAL-AJU-03","nome":"Exportar Auditoria de Ajustes","desc":"Permite ao validador exportar em CSV todas as rodadas de ajuste fechadas de uma inscrição, gerando uma linha por alteração para servir de evidência documental.","objeto":"**ALI: Inscrição** · entidade de suporte (snapshots de estado da inscrição por rodada/etapa)","uso":"","estado":"rascunho","prioridade":"P3","mvp":false,"path":"modules/validacao/ajustes/f-exportar-auditoria-ajustes.md","codigo":{"back":[],"front":[]}},{"id":"VAL-AJU-04","nome":"Conferir Item de Ajuste","desc":"Permite ao validador marcar, item a item, quais dos ajustes solicitados ao participante já foram atendidos, deixando visível quanto ainda falta antes de decidir sobre a inscrição.","objeto":"**ALI: Inscrição** · entidade de suporte (itens de ajuste solicitado ⚠️ — vinculados ao histórico; consumidos pela Validação)","uso":"","estado":"rascunho","prioridade":"P1","mvp":true,"path":"modules/validacao/ajustes/f-conferir-item-ajuste.md","codigo":{"back":[],"front":[]}}]},{"nome":"Análise e Decisão","sigla":"VAL-ANA","desc":"Concentra a análise detalhada da inscrição e a decisão do administrador sobre ela. A partir do detalhe completo — dados do formulário, questionário, documentos, equipe, termos e histórico —, o administrador inicia a validação e a conclui aprovando ou rejeitando a inscrição, sempre com o parecer registrado. Aprovar e Rejeitar são ações distintas: cada uma é uma feature própria, com regras de parecer diferentes.","path":"modules/validacao/analise-decisao/README.md","feats":[{"id":"VAL-ANA-01","nome":"Detalhar Inscrição","desc":"Permite ao validador detalhar uma inscrição em modo leitura, reunindo os dados do formulário, o questionário, os documentos, a equipe, os termos e o histórico de validação para embasar a decisão.","objeto":"**ALI: Inscrição** · entidade principal","uso":"","estado":"rascunho","prioridade":"P1","mvp":true,"path":"modules/validacao/analise-decisao/f-detalhar-inscricao.md","codigo":{"back":[],"front":[]}},{"id":"VAL-ANA-02","nome":"Iniciar Validação","desc":"Permite ao validador iniciar a validação de uma inscrição finalizada, assumindo-a para análise e movendo a sua situação de Finalizada para Em Validação.","objeto":"**ALI: Validação Inscrição** · entidade principal","uso":"","estado":"rascunho","prioridade":"P1","mvp":true,"path":"modules/validacao/analise-decisao/f-iniciar-validacao.md","codigo":{"back":[],"front":[]}},{"id":"VAL-ANA-03","nome":"Aprovar Inscrição","desc":"Permite ao validador concluir a validação aprovando a inscrição, com parecer opcional, de modo que ela passe à situação Validada e siga para a etapa de avaliação.","objeto":"**ALI: Validação Inscrição** · entidade principal","uso":"","estado":"rascunho","prioridade":"P1","mvp":true,"path":"modules/validacao/analise-decisao/f-aprovar-inscricao.md","codigo":{"back":[],"front":[]}},{"id":"VAL-ANA-04","nome":"Rejeitar Inscrição","desc":"Permite ao validador concluir a validação rejeitando a inscrição, mediante parecer obrigatório, de modo que ela passe à situação Rejeitada e seja encerrada.","objeto":"**ALI: Validação Inscrição** · entidade principal","uso":"","estado":"rascunho","prioridade":"P1","mvp":true,"path":"modules/validacao/analise-decisao/f-rejeitar-inscricao.md","codigo":{"back":[],"front":[]}},{"id":"VAL-ANA-05","nome":"Editar Inscrição Validada","desc":"Permite ao administrador nacional corrigir os dados de uma inscrição que já foi validada — respostas do formulário, respostas do questionário, enquadramento, membros da equipe e anexos — mediante justificativa, guardando o estado antes e depois da correção para consulta posterior.","objeto":"**ALI: Inscrição** · entidade principal","uso":"","estado":"rascunho","prioridade":"P2","mvp":false,"path":"modules/validacao/analise-decisao/f-editar-inscricao-validada.md","codigo":{"back":[],"front":[]}},{"id":"VAL-ANA-06","nome":"Excluir Inscrição Validada","desc":"Permite ao administrador nacional retirar da premiação uma inscrição já validada, mediante justificativa, mantendo os dados preservados para consulta e auditoria.","objeto":"**ALI: Inscrição** · entidade principal","uso":"","estado":"rascunho","prioridade":"P2","mvp":false,"path":"modules/validacao/analise-decisao/f-excluir-inscricao-validada.md","codigo":{"back":[],"front":[]}}]},{"nome":"Fila e Painel de Validação","sigla":"VAL-FIL","desc":"Reúne a porta de entrada da validação: a fila das inscrições submetidas em cada UF, com filtros em cascata e cards de indicadores por status, e o painel gerencial que consolida as métricas de validação em gráficos. É onde o administrador localiza a inscrição a analisar, acompanha o andamento consolidado antes de decidir e exporta o histórico das inscrições que sustentam as métricas. Para o Administrador Regional, o escopo é sempre restrito às UFs a que ele está vinculado.","path":"modules/validacao/fila-validacao/README.md","feats":[{"id":"VAL-FIL-01","nome":"Pesquisar Inscrições para Validação","desc":"Permite ao validador pesquisar as inscrições submetidas para validação por unidade federativa, premiação, categoria, modalidade, tipo de participante e situação, listando os resultados para conferência e análise.","objeto":"**ALI: Inscrição** · entidade principal","uso":"","estado":"rascunho","prioridade":"P1","mvp":true,"path":"modules/validacao/fila-validacao/f-pesquisar-inscricao.md","codigo":{"back":[],"front":[]}},{"id":"VAL-FIL-02","nome":"Acompanhar Painel de Validação","desc":"Permite ao validador acompanhar as métricas de validação de uma premiação, com a distribuição das inscrições por situação e a comparação por categoria ou por unidade federativa.","objeto":"**ALI: Inscrição** · entidade principal","uso":"","estado":"rascunho","prioridade":"P2","mvp":false,"path":"modules/validacao/fila-validacao/f-acompanhar-painel-validacao.md","codigo":{"back":[],"front":[]}},{"id":"VAL-FIL-03","nome":"Exportar Histórico do Painel de Validação","desc":"Permite ao administrador levar para fora do sistema o histórico das inscrições que sustentam as métricas do painel de validação, em uma planilha com uma linha por inscrição acrescida do nome e do telefone de contato do participante.","objeto":"**ALI: Inscrição** · entidade principal","uso":"A exportação parte do próprio painel gerencial, pela ação \"Exportar Excel\": o recorte já aplicado nos filtros do painel é o mesmo da planilha, e o arquivo é disponibilizado para download.","estado":"rascunho","prioridade":"P2","mvp":false,"path":"modules/validacao/fila-validacao/f-exportar-historico-painel.md","codigo":{"back":[],"front":[]}}]}]}],"kpi":{"dominios":5,"fss":21,"feats":128,"fssVazios":0,"domsVazios":0,"codBackend":null,"codFrontend":null,"featComBack":0,"featComFront":0,"arqBack":0,"arqFront":0,"featComObjeto":128,"featComUso":4},"registros":{"back":[],"front":[]}};
